{
  "findings": [
    {
      "check_id": "CKV_AWS_126",
      "title": "EC2 detailed monitoring is not enabled",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The instance does not enable detailed monitoring, reducing the granularity of CloudWatch metrics available for security monitoring and incident investigation."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "EC2 Instance Metadata Service v1 is enabled",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "Without requiring IMDSv2 tokens, the instance can accept IMDSv1 requests, increasing the risk of metadata and credential theft through server-side request forgery."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "EC2 root EBS volume encryption is not enforced",
      "resource": "aws_instance.MyFirstInstnace",
      "severity": "MEDIUM",
      "explanation": "The instance does not explicitly encrypt its root EBS volume, so data at rest could be stored unencrypted depending on the selected AMI and account defaults."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"MyFirstInstnace\" {\n  ami                         = lookup(var.AMIS, var.AWS_REGION)\n  instance_type               = \"t2.micro\"\n  availability_zone           = \"us-east-2a\"\n  key_name                    = aws_key_pair.levelup_key.key_name\n  vpc_security_group_ids      = [aws_security_group.allow-levelup-ssh.id]\n  subnet_id                   = aws_subnet.levelupvpc-public-1.id\n  monitoring                  = true\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}\n",
  "fix_summary": "Enabled detailed CloudWatch monitoring, required IMDSv2 session tokens, and enforced encryption for the instance's root EBS volume. No IAM role was added because this file does not establish that the instance requires AWS API access, and EBS optimization was not treated as a security control."
}
